/**
 * Carries a saved canvas change into the hand-written page files of the website's code project.
 *
 * Pages that are a pure projection of the visual document are regenerated by the server when the
 * document is saved. Pages holding hand-written code are held back from regeneration; for those,
 * the server plans the element edits for the change (before/after visual document) and this
 * module applies them one by one through the visual-to-code mutation endpoint, bound to the
 * file revision. Nothing here writes a file directly, and no outcome is assumed: every edit is
 * reported as applied, unchanged, rejected or blocked by a revision conflict.
 */
import type { VisualSourceMutation, VisualSourceSyncResult } from "./forgeProjectService";

export interface PlannedCanvasEdit {
  elementId: string;
  mutation: VisualSourceMutation;
}

export interface CanvasEditPlan {
  files: Array<{
    filePath: string;
    version: number;
    edits: PlannedCanvasEdit[];
    unsupported: Array<{ elementId?: string; reason: string }>;
  }>;
  skipped: Array<{ filePath: string; reason: string }>;
}

/** A structured failure from the API (for example a 409 revision conflict). */
interface ApiErrorEnvelope {
  success: false;
  error?: { code?: string; message?: string };
  message?: string;
}

/** The parts of forgeProjectService this module needs; injected so it can be tested against a real server. */
export interface CanvasSourceApi {
  planVisualToCode(projectId: string, body: { before: unknown; after: unknown; paths?: string[] }): Promise<CanvasEditPlan>;
  syncVisualToCode(
    projectId: string,
    filePath: string,
    element: { id: string },
    options: { mutation: VisualSourceMutation; expectedRevision: number }
  ): Promise<VisualSourceSyncResult | ApiErrorEnvelope>;
  readFile(projectId: string, filePath: string): Promise<{ file: { version: number } }>;
}

export interface CanvasEditRejection {
  elementId: string;
  mutation: VisualSourceMutation["type"];
  code: string;
  message: string;
}

export interface CanvasFileOutcome {
  filePath: string;
  /** Edits that changed the stored source. */
  applied: number;
  /** Edits the source already satisfied; no file version was created for them. */
  unchanged: number;
  rejected: CanvasEditRejection[];
  unsupported: Array<{ elementId?: string; reason: string }>;
  /** Set when the file kept changing underneath the edits; the remaining edits were not applied. */
  conflict?: string;
  version: number;
}

export interface CanvasSourceSyncOutcome {
  files: CanvasFileOutcome[];
  skipped: Array<{ filePath: string; reason: string }>;
  /** Set when planning or the transport failed; edits not listed in `files` were not attempted. */
  error?: string;
}

const isEnvelope = (value: unknown): value is ApiErrorEnvelope =>
  !!value && typeof value === "object" && !("updated" in (value as object));

export async function syncCanvasEditsToSource(
  api: CanvasSourceApi,
  input: { projectId: string; before: unknown; after: unknown; paths?: string[] }
): Promise<CanvasSourceSyncOutcome> {
  const outcome: CanvasSourceSyncOutcome = { files: [], skipped: [] };
  let plan: CanvasEditPlan;
  try {
    plan = await api.planVisualToCode(input.projectId, { before: input.before, after: input.after, paths: input.paths });
  } catch (err) {
    return { ...outcome, error: err instanceof Error ? err.message : "The source edits could not be planned." };
  }
  outcome.skipped = plan.skipped ?? [];

  for (const file of plan.files ?? []) {
    const result: CanvasFileOutcome = {
      filePath: file.filePath,
      applied: 0,
      unchanged: 0,
      rejected: [],
      unsupported: file.unsupported ?? [],
      version: file.version,
    };
    outcome.files.push(result);
    let refreshed = false;

    for (let i = 0; i < file.edits.length; i++) {
      const edit = file.edits[i];
      let response: VisualSourceSyncResult | ApiErrorEnvelope;
      try {
        response = await api.syncVisualToCode(input.projectId, file.filePath, { id: edit.elementId }, {
          mutation: edit.mutation,
          expectedRevision: result.version,
        });
      } catch (err) {
        outcome.error = err instanceof Error ? err.message : "The source edit request failed.";
        return outcome;
      }

      if (isEnvelope(response)) {
        const code = response.error?.code ?? "REQUEST_REJECTED";
        const message = response.error?.message ?? response.message ?? "The edit was not accepted.";
        if (code === "REVISION_CONFLICT") {
          // The file changed since it was planned. Re-read its revision once and let the server
          // validate the same edit against the current source; never write over it blindly.
          if (!refreshed) {
            refreshed = true;
            try {
              result.version = (await api.readFile(input.projectId, file.filePath)).file.version;
              i--;
              continue;
            } catch (err) {
              result.conflict = err instanceof Error ? err.message : message;
              break;
            }
          }
          result.conflict = message;
          break;
        }
        result.rejected.push({ elementId: edit.elementId, mutation: edit.mutation.type, code, message });
        continue;
      }

      if (response.success && response.updated) {
        result.applied++;
        result.version = response.version ?? result.version + 1;
      } else if (response.success) {
        result.unchanged++;
      } else {
        result.rejected.push({
          elementId: edit.elementId,
          mutation: edit.mutation.type,
          code: response.code ?? "REJECTED",
          message: response.diagnostics?.[0]?.message ?? "The edit was not applied.",
        });
      }
    }
  }
  return outcome;
}

/**
 * The editor's post-save step: when the acknowledged save reports pages that were held back from
 * regeneration, send this save's canvas change (document before → after) to them. Returns
 * undefined when there is nothing to send: no code project, no held page, or no earlier document.
 */
export async function syncAcknowledgedSave(
  api: CanvasSourceApi,
  acknowledgement: { codeSync?: { projectId?: string; conflicts?: string[] } },
  before: unknown,
  after: unknown
): Promise<CanvasSourceSyncOutcome | undefined> {
  const projectId = acknowledgement.codeSync?.projectId;
  const heldPages = acknowledgement.codeSync?.conflicts;
  if (!before || !after || !projectId || !heldPages?.length) return undefined;
  return syncCanvasEditsToSource(api, { projectId, before, after, paths: heldPages });
}

/** One line for the editor's status area, or null when there is nothing to report. */
export function describeCanvasSourceSync(outcome: CanvasSourceSyncOutcome | undefined): { text: string; isProblem: boolean } | null {
  if (!outcome) return null;
  const applied = outcome.files.reduce((n, f) => n + f.applied, 0);
  const problems: string[] = [];
  if (outcome.error) problems.push(outcome.error);
  for (const file of outcome.files) {
    if (file.conflict) problems.push(`${file.filePath} changed in the Code Workspace and the remaining edits were not applied`);
    for (const r of file.rejected) problems.push(`${file.filePath} › ${r.elementId}: ${r.message}`);
    for (const u of file.unsupported) problems.push(`${file.filePath}${u.elementId ? ` › ${u.elementId}` : ""}: ${u.reason}`);
  }
  if (applied === 0 && problems.length === 0) return null;
  const head = applied > 0 ? `${applied} edit${applied === 1 ? "" : "s"} applied to hand-written page source.` : "";
  if (problems.length === 0) return { text: head, isProblem: false };
  const shown = problems.slice(0, 3).join("; ");
  const more = problems.length > 3 ? ` (and ${problems.length - 3} more)` : "";
  return { text: `${head} Not applied to hand-written source: ${shown}${more}. Resolve these in the Code Workspace.`.trim(), isProblem: true };
}
